// src/tests/shared/components/icons/OtsSprites.spec.ts
//
// The ots sprite (generated by scripts/globes/build.mjs) is loaded the same
// way as every other icon library: App.vue mounts each component in
// iconLibraryComponents, and OIcon renders <use href="#<collection>-<name>">.
// These specs guard that path and catch a jurisdiction mapped to an ots icon
// whose preset was never built into the sprite.

import { mount } from '@vue/test-utils';
import { describe, it, expect } from 'vitest';
import OIcon from '@/shared/components/icons/OIcon.vue';
import { iconLibraries, iconLibraryComponents } from '@/shared/components/icons/sprites';
import { JURISDICTION_ICONS } from '@/sources/jurisdictions';

const mountSprite = async () => {
  const { default: OtsSprites } = await iconLibraryComponents.ots();
  return mount(OtsSprites);
};

describe('OtsSprites', () => {
  it('is registered for App.vue to load and for the icon gallery', () => {
    expect(iconLibraryComponents).toHaveProperty('ots');
    expect(iconLibraries.ots.usagePrefix).toBe('ots');
  });

  it('defines a symbol for every jurisdiction mapped to the ots collection', async () => {
    const wrapper = await mountSprite();
    const ids = wrapper.findAll('symbol').map((s) => s.attributes('id'));

    const expected = Object.values(JURISDICTION_ICONS)
      .filter((icon) => icon.collection === 'ots')
      .map((icon) => `ots-${icon.name}`);

    expect(expected.length).toBeGreaterThan(0);
    expect(ids).toEqual(expect.arrayContaining(expected));
  });

  it('draws every symbol in currentColor on the fa6 earth geometry', async () => {
    const wrapper = await mountSprite();
    const symbols = wrapper.findAll('symbol');
    expect(symbols.length).toBeGreaterThan(0);

    for (const symbol of symbols) {
      expect(symbol.attributes('viewBox')).toBe('0 0 512 512');
      const paths = symbol.findAll('path');
      expect(paths.length).toBeGreaterThan(0);
      for (const path of paths) expect(path.attributes('fill')).toBe('currentColor');
      // first path is the r=256 disc with land cut out
      expect(paths[0].attributes('d')).toMatch(/^M0 256a256 256 0 1 1 512 0/);
    }
  });

  it('is referenced by OIcon with collection="ots"', () => {
    const wrapper = mount(OIcon, { props: { collection: 'ots', name: 'earth-canada' } });
    expect(wrapper.find('use').attributes('href')).toBe('#ots-earth-canada');
  });
});
